struct ValidatorAuthBinding {
  Bits256 identity{}, stake_id{};
  bool operator==(const ValidatorAuthBinding& other) const {
    return identity == other.identity && stake_id == other.stake_id;
  }
  bool operator!=(const ValidatorAuthBinding& other) const {
    return !(*this == other);
  }
};

